-- Phase 4 (database), part 2: the 23 Tribe Cards for the goals that are already live, loaded as drafts.
-- Each carries its leadership demand and its sensitive flag. Nothing here creates a goal or touches a weekly idea.
-- Looks up every community and goal family by slug; a missing one stops the migration.
do $seed$

declare v_n integer;
begin
  insert into public.tribe_card_templates (
    slug, community_id, family_id, title, sort,
    who_for, loving_god, loving_others, loving_life, week12_outcome, arc_1, arc_2, arc_3, guardrail, track_slugs,
    rhythm_slot, rhythm_mode, who_leads_well, demand_structure, demand_connection, demand_teaching, demand_doing, sensitive)
  select v.slug, c.id, f.id, v.title, v.sort,
         v.who_for, v.loving_god, v.loving_others, v.loving_life, v.week12_outcome, v.arc_1, v.arc_2, v.arc_3, v.guardrail, v.track_slugs,
         v.rhythm_slot, v.rhythm_mode, v.who_leads_well, v.ds, v.dc, v.dt, v.dd, v.sensitive
    from (values
('launch-or-formalise-a-business','business-entrepreneurship','enterprise','Launch or formalise a business',1,'Anyone with a business idea, or a business that runs on handshakes and needs to be made official.','We bring our plans to God each week and start with honesty about what we can and cannot do.','We test each other''s ideas, share what we learn about the law and the market, and cheer every first step.','By week 12 each of us has a registered or clearly planned business, a business account and a first sale or a dated plan for one.','A registered or clearly planned business, and a first sale or a dated plan for one.','Write down who your first ten customers are and what problem you solve for each of them.','Take the next legal or practical step: register the name with the CAC, open a business account or make your first sale.','Set a 90-day plan with one revenue target, and ask one person in the tribe to check on it monthly.','Leaders do not give legal, tax or investment advice. They point to a qualified professional.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has started or formalised a business and remembers what the first steps cost. Keeps a group moving week to week.',3,1,2,3,false),
('grow-revenue-and-systems','business-entrepreneurship','enterprise','Grow revenue and systems',2,'Owners whose business works but depends on them, and who want steady growth without losing their family or their faith.','We commit our work to God each week and ask for wisdom on one decision at a time.','We share our numbers with each other honestly, borrow each other''s best methods and carry each other''s pressure.','By week 12 each of us tracks one health number every week, has one process someone else can run and has talked with our best customers.','One weekly number tracked, one process handed over, and a plan built on what the best customers value.','Pick one number that tells you if the business is healthy and record it every week.','Write down one process that depends only on you and make it simple enough for someone else to do.','Ask your five best customers what they value most, then do more of it.','Leaders do not give legal, tax or investment advice. They point to a qualified professional.',array['builders','stewards']::text[],'weeknight-evening','online','Has grown a business past the founder stage and put simple systems in place. Asks good questions about numbers.',3,1,2,2,false),
('step-into-a-leadership-role','professionals','career-calling','Step into a leadership role',1,'Employees who are being asked to lead, or want to be, and want to do it with integrity.','We bring our work to God each week and ask Him to make us leaders who serve before we direct.','We share real situations from work, listen before advising and pray for each other''s teams by name, without breaking confidence.','By week 12 each of us has taken one visible leadership responsibility, asked a leader for guidance and written down how we want to lead.','One visible leadership step taken, a conversation with a leader had, and a short written leadership approach.','Name the leadership role you want and the three skills it needs. Rate yourself honestly on each.','Ask a leader you respect for twenty minutes and bring two questions. Act on one thing they say.','Take one visible responsibility at work, in church or in the community, and report back to the tribe.','Leaders do not give legal or HR advice and never ask members to name colleagues or share private company information.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has led people at work and can speak honestly about mistakes. Draws out others before giving an opinion.',2,3,3,2,false),
('change-career-direction-with-confidence','professionals','career-calling','Change career direction with confidence',2,'Professionals who sense the current path is wrong and want to move wisely, not in a panic.','We ask God what He has put in us and we are willing to wait on Him before we leap.','We listen to each other''s stories without rushing to fix them and open doors for one another where we can.','By week 12 each of us has named our strengths and interests, spoken to two people in the field and run one small test of the new direction.','Strengths named, two conversations with people in the field, and one small test done.','List what you enjoy, what you are good at and what the market pays for. Look for the overlap.','Speak to two people already in the field you are considering and ask what they wish they had known.','Try a small test before you commit: a short course, a side project or a week of shadowing.','Leaders do not tell anyone to quit a job. They help members think and let them decide.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has changed careers or helped others do so, and can sit with uncertainty without hurrying people.',2,3,2,2,false),
('build-a-steady-client-pipeline','consulting','enterprise','Build a steady client pipeline',1,'Independent consultants and freelancers whose work arrives in waves and who want it to be steady.','We ask God for provision and the discipline to ask for work without fear or pride.','We introduce one another to clients, practise how we describe our work and celebrate every enquiry.','By week 12 each of us has a list of people to contact, a weekly outreach hour kept and at least two new conversations with possible clients.','A contact list, a weekly outreach hour kept, and two new client conversations.','List twenty people who could hire you or refer you, and contact five this week.','Ask two past clients for a short testimonial and one introduction.','Set a weekly hour for outreach and keep it, whatever the week looks like.','Leaders do not give legal, tax or financial advice. They point to a qualified professional.',array['builders','stewards']::text[],'weeknight-evening','online','Has built a consulting or freelance practice from nothing and still does outreach every week.',3,1,2,3,false),
('price-and-package-my-expertise','consulting','enterprise','Price and package my expertise',2,'Consultants who charge by the hour or by guesswork and want clear, confident offers.','We ask God to free us from the fear of asking, and from the love of money, so that we price fairly.','We review each other''s offers, practise saying the price aloud and refuse to let each other undercharge.','By week 12 each of us has one clear package with a scope, a timeline and a price, and has offered it to a real client.','One clear package with scope, timeline and price, offered to a real client.','Write down what you charge today and what the result is worth to the client. Notice the gap.','Turn what you do into a clear package with a scope, a timeline and a price.','Raise your price for the next new client, and practise saying it aloud first.','Leaders do not give legal, tax or financial advice. They point to a qualified professional.',array['builders','stewards']::text[],'weeknight-evening','online','Sells packaged services at a fair price and can explain how they arrived at it.',2,1,3,2,false),
('land-my-next-role','in-between-jobs','career-calling','Land my next role',1,'People between jobs who want a clear search, company on the road and a role that fits.','We trust God for provision, and we ask Him to keep us from panic and from shame.','We share leads, review each other''s applications and pray for each other before every interview.','By week 12 each of us has an up-to-date CV and profile, a weekly search rhythm and at least five conversations or interviews.','An updated CV and profile, a weekly search rhythm and five conversations or interviews.','Update your CV and your LinkedIn profile this week, and ask one person to read them with you.','Send five focused applications or messages a week, and ask for one introduction each week.','Keep a short list of interviews and follow-ups, and thank everyone who helped you, even if it did not lead anywhere.','Leaders do not promise jobs or take payment for introductions. They share leads freely and honestly.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has been through a job search and can keep people moving without false cheer.',3,2,1,3,false),
('retool-with-new-skills','in-between-jobs','career-calling','Retool with new skills',2,'People between jobs who see that the roles they want ask for skills they lack.','We use this season to grow, and we ask God for patience with the time it takes.','We study together, check each other''s progress and show our work to one another before we show it to employers.','By week 12 each of us has chosen one skill, built something small with it and shown it to someone who hires.','One skill chosen, one small piece of work built, and shown to someone who hires.','Pick one skill the roles you want keep asking for and find one free or low-cost way to start.','Build something small that shows the skill, such as a sample, a project or a short write-up.','Share what you built with someone who hires, and ask what would make it stronger.','Leaders do not sell courses or take payment from members. They share only free resources and what worked for them.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has learned a new skill while out of work or retooled their career. Keeps others learning.',3,1,3,2,false),
('thrive-in-a-long-distance-family','global-citizens','relationships','Thrive in a long-distance family',1,'People living apart from close family who want to stay close in heart and in habit.','We bring our families to God by name each week and trust Him to hold them where we cannot.','We share what works for staying close, pray for each other''s families and notice when someone is carrying homesickness.','By week 12 each of us has a regular time to call each close family member, one shared activity each month and a message of thanks sent.','Regular calls kept, one shared monthly activity and a message of thanks sent.','Agree a regular time to call each close family member, and keep to it for the whole season.','Plan one thing to do together online each month, such as a meal, a prayer, a game or a devotional.','Write a letter or voice note of thanks to someone at home and send it.','Leaders do not take sides in family disputes or give counselling. Serious needs go to the care ladder.',array['rising','builders','stewards','sages']::text[],'sunday-afternoon','online','Lives or has lived far from family and stayed close. Warm and attentive to people who feel alone.',2,3,1,2,false),
('make-a-cross-border-move-well','global-citizens','relationships','Make a cross-border move well',2,'People planning to move to another country, or in the first months after a move.','We bring each step of the move to God and ask Him to go before us.','We share lists, contacts and honest lessons, and we welcome each other as neighbours before we arrive.','By week 12 each of us has a dated move plan, has spoken with someone already there and has a plan for finding a church family on arrival.','A dated move plan, a conversation with someone already there, and a plan to find a church family.','Write the full list of what the move needs: documents, money, housing and people. Put a date next to each item.','Find one person already living where you are going and ask what they would do differently.','Plan your first month there, including how you will find a church family from week one.','Leaders do not give immigration, legal or tax advice. They point to a qualified professional.',array['rising','builders','stewards']::text[],'sunday-afternoon','online','Has moved country and can explain the real costs and surprises. Practical and encouraging.',3,2,3,2,false),
('strengthen-our-marriage','marriage-relationships','relationships','Strengthen our marriage',1,'Married couples who want a stronger marriage and are willing to do small things every week.','We pray for our spouse and with our spouse every week, and put God at the centre of our decisions.','We listen before we respond, serve each other every day, and settle hurts quickly instead of keeping score.','By week 12 we have a monthly date, a shared budget and one new habit we have kept for twelve weeks.','A monthly date, a shared budget and one habit kept.','Set a weekly time to talk, with phones away, and begin each time by naming one thing you appreciate.','Pray together every day this month, even for two minutes.','Plan one date or day away that you both look forward to, and agree what you want it to do for the marriage.','Leaders host and encourage. They do not counsel couples or take sides. Serious cases go to the care ladder.',array['builders','stewards','sages']::text[],'sunday-afternoon','in_person','Has a marriage that has been tested and held. Humble, warm and discreet. Never presents their own marriage as the model.',2,3,2,1,true),
('prepare-well-for-marriage','marriage-relationships','relationships','Prepare well for marriage',2,'Engaged couples, and people in a serious relationship heading toward marriage.','We ask God to prepare us as people before we prepare for a wedding, and we pray for our future home.','We ask each other honest questions, listen to couples who have gone before us and respect each person''s pace and purity.','By week 12 each of us has talked openly about money, children, family and faith, and has booked pre-marriage counselling or a class.','Money, children, family and faith discussed openly, and pre-marriage counselling or a class booked.','Write what you hope for in a marriage and what you are growing in. Share it with a trusted mentor.','Talk openly about money, children, family and faith, and note where you agree and where you do not.','Book your pre-marriage counselling or class, and ask a married couple to walk with you.','Leaders do not counsel couples or advise on whether to marry. They host, encourage and point to the pastoral team.',array['rising','builders']::text[],'sunday-afternoon','in_person','Married for several years and willing to speak plainly about preparation. Discreet and warm.',2,3,3,1,true),
('rebuild-after-a-relationship-ends','marriage-relationships','relationships','Rebuild after a relationship ends',3,'People recovering from a broken engagement, a breakup, a divorce or the loss of a spouse, who want company and a steady way forward.','We bring our grief and our questions to God honestly and trust Him to heal at a pace that is right for each of us.','We listen without fixing, keep each other''s stories private and show up for each other on the hard days.','By week 12 each of us has a daily habit that steadies us, one safe person we talk to often and a clear next step for the season ahead.','A steadying daily habit, a safe person to talk to and one clear next step.','Give yourself space to grieve, and tell one safe person how you are really doing.','Return to one habit that keeps you steady, such as prayer, exercise, rest or time with friends.','Name what you want to carry forward and what you are leaving behind, and share it with the tribe.','Leaders do not counsel or diagnose, and never press anyone to share more than they want to. Serious grief or risk goes to the care ladder the same day.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has walked through a loss themselves, or has long experience of sitting with people in grief. Gentle, patient and discreet.',1,3,1,2,true),
('build-a-faith-filled-home-rhythm','parents-family','faith-home','Build a faith-filled home rhythm',1,'Parents and carers who want a simple, regular time of faith in the home, whatever the age of the children.','We make room each day for God at home, even briefly, and we thank Him together as a family.','We swap ideas that worked, encourage each other when we miss a day and pray for each other''s children by name.','By week 12 each of us has a family faith moment most days, a set of family values written down and a home where the children can see it.','A family faith moment most days, and the family''s top values written where all can see them.','Choose one daily moment, such as a meal, bedtime or the car ride, to pray or read together as a family.','Let each child choose a Bible story or a song for the family this week.','Write your family''s top three values and put them where everyone can see them.','Leaders do not give parenting rules or counsel families. If a child may be at risk, they use the care ladder the same day.',array['builders','stewards','sages']::text[],'sunday-evening','online','Has a home with a steady faith rhythm and is honest about the days it fails. Warm and unshowy.',3,2,2,3,false),
('parent-teenagers-well','parents-family','faith-home','Parent teenagers well',2,'Parents and carers of teenagers who want to stay connected, clear and kind through hard years.','We pray for our teenagers each day and ask God to make us parents they can trust.','We listen to each other''s stories without judging, keep what is shared in the tribe and remember that every teenager is different.','By week 12 each of us has had a ten-minute listening time with our teenager each week, agreed one clear boundary together and done one thing they enjoy.','Weekly listening time, one clear boundary agreed together and one shared enjoyable activity.','Listen for ten minutes with no advice. Ask one question you do not know the answer to.','Agree one clear boundary with your teenager and the reason for it, and let them help set it.','Do something your teenager enjoys, and let them lead it.','Leaders do not give parenting rules or counsel families. If a child may be at risk, they use the care ladder the same day.',array['builders','stewards']::text[],'sunday-evening','online','Has raised or is raising teenagers, and is honest about mistakes. Calm and slow to give advice.',2,3,2,2,false),
('build-a-consistent-fitness-habit','health-fitness-sports','health','Build a consistent fitness habit',1,'Anyone who starts fitness plans and stops, and wants a steady habit with company.','We treat our bodies as a gift from God, and we ask Him for discipline that comes from love, not shame.','We check in with each other on our training days, celebrate small wins and never mock anyone''s pace.','By week 12 each of us has a weekly movement habit we have kept for twelve weeks, a training partner and a goal we can measure.','A weekly movement habit kept for the season, a training partner and a measurable goal.','Choose one activity you can do on your worst day, and do it three times this week.','Find a partner in the tribe and agree the days you will check in with each other.','Set a goal you can measure, such as a distance, a weight or a time, and mark the date.','Leaders do not give medical advice, diets or exercise for a condition. Members see a doctor first where there is any doubt.',array['rising','builders','stewards','sages']::text[],'saturday-morning','in_person','Keeps a regular fitness habit and remembers starting from zero. Encouraging and never competitive.',3,2,1,3,false),
('reach-a-health-milestone','health-fitness-sports','health','Reach a health milestone',2,'Anyone with a clear health goal, such as a check-up, a test result, a certain weight or a fitness target.','We thank God for the body we have and ask Him for patience with the pace of change.','We encourage without comparing, keep what is shared private and celebrate every step, whatever its size.','By week 12 each of us has written our milestone with a date, booked any check-up we needed and made steady progress we can see.','A written milestone with a date, any needed check-up done and steady progress recorded.','Write your milestone with a date, and book any check-up or test you have been putting off.','Break the milestone into four monthly steps and record where you are each week.','Plan how you will keep it going after the milestone, so that it is a way of life and not a moment.','Leaders do not give medical advice, diets or targets for any person''s weight, and never ask anyone to share test results. Members follow their doctor''s advice.',array['builders','stewards','sages']::text[],'saturday-morning','in_person','Has reached a health milestone and stayed steady after it. Never preachy and never competitive.',3,2,2,2,true),
('excel-in-my-studies-or-exams','education','learning','Excel in my studies or exams',1,'Students at any level who want to study well, stay steady under pressure and finish strong.','We study as an act of worship, we rest on the day set apart and we trust God with the results.','We study together, explain hard ideas to each other and encourage anyone who is afraid.','By week 12 each of us has a study timetable we keep, a weekly study partner and at least two timed practice papers done.','A study timetable kept, a weekly study partner and two timed practice papers done.','Make a study timetable that fits your real life, and share it with one person who will ask how it is going.','Study with one or two others once a week and teach each other the hardest topics.','Do past papers under timed conditions, and learn from every mistake.','Leaders do not do members'' work for them or help anyone cheat. They help members study honestly.',array['rising','builders']::text[],'weeknight-evening','online','Has studied hard and honestly, and can explain how they kept going. Patient with those who are afraid of exams.',3,1,3,2,false),
('grow-as-an-educator','education','learning','Grow as an educator',2,'Teachers, lecturers and trainers who want to grow in their craft and in their care for learners.','We see our teaching as a calling, and we ask God for patience, wisdom and a heart for every learner.','We watch each other''s lessons kindly, share what worked and pray for our classes and students by first name only.','By week 12 each of us has chosen one thing to improve, tried a new method and had a colleague watch a lesson.','One teaching skill chosen, a new method tried and a lesson watched by a colleague.','Choose one thing in your teaching to improve this season and ask a colleague to watch one lesson.','Try one new method with your class and note what the students say.','Write down one lesson you will keep and share it with another teacher.','Leaders never share names, records or private details of any student. Only first names, and only with care.',array['builders','stewards']::text[],'weeknight-evening','online','Teaches well and keeps learning. Generous with their classroom and open to feedback.',2,2,3,3,false),
('sustain-my-calling-without-burning-out','medical-healthcare','career-calling','Sustain my calling without burning out',1,'Doctors, nurses, pharmacists and health workers who feel the weight of the work and want to keep going well.','We keep a daily pause with God, even five minutes between shifts, and treat our work as a calling, not only a job.','We check on each other between shifts, carry each other''s prayer needs, and say no to over-giving together.','By week 12 each of us has a rest day we protect, a sleep pattern that works and one work boundary we have kept.','A protected rest day and one kept work boundary.','List what drains you and what restores you. Protect one restoring thing this week.','Set one boundary on your time and tell someone who will help you keep it.','Plan a proper rest, a day or more, in the next quarter and put it in your calendar now.','Leaders give no medical advice and never discuss patients. Names and cases stay out of the tribe.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has worked in healthcare long enough to know the cost, and has learned to rest. Gentle, discreet and not heroic.',2,3,1,1,true),
('advance-my-specialisation','medical-healthcare','career-calling','Advance my specialisation',2,'Health workers working toward a specialty, a higher qualification or a senior post.','We see our training as stewardship of a gift, and we ask God for diligence and humility.','We share study plans, prepare each other for exams and interviews and celebrate every step.','By week 12 each of us has the next exam, certificate or posting written with a date, a mentor in view and a weekly study block we keep.','The next qualification written with a date, a mentor in view and a weekly study block kept.','Write the next exam, certificate or posting you need and the date you want it by.','Find a mentor already where you want to be and ask for a regular conversation.','Set a weekly study block and protect it, even on busy weeks.','Leaders give no medical advice and never discuss patients. Names and cases stay out of the tribe.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has progressed through specialist training and knows the demands. Practical and supportive.',3,1,3,2,false),
('finish-and-release-a-body-of-work','creative-economy','enterprise','Finish and release a body of work',1,'Makers who have started more than they have finished and want to finish and share one piece of work.','We offer our work to God as an act of worship and ask Him for the courage to finish and to share.','We give honest, kind feedback, keep each other to deadlines and show up when work is released.','By week 12 each of us has defined what finished means, worked on it most days and shared it with a small audience.','A defined piece of work finished and shared with a small audience.','Choose the work you will finish. Write what finished means, and the date.','Work on it at the same time every day for a month, and mark each day you do.','Release it to a small audience first, and ask three people for honest feedback.','Leaders do not judge anyone''s faith by the style or subject of their work. Content must be fit for a church family.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Has finished and released creative work and knows the struggle between starting and finishing. Honest and encouraging.',3,2,1,3,false),
('turn-my-craft-into-income','creative-economy','enterprise','Turn my craft into income',2,'Makers who want their craft to earn, without losing their joy or their integrity.','We bring our gifts to God, and we ask for wisdom to price, sell and give with a clean heart.','We share leads, introduce each other to buyers and tell each other honestly what we think of each other''s prices.','By week 12 each of us has clear prices, a place to sell and offered our work to at least ten people.','Clear prices, a place to sell and the work offered to ten people.','Decide who would pay for your craft and what they would pay for, and ask three of them.','Put a price on one thing you make and offer it to ten people this month.','Set up a simple way to be paid and to be found, such as a page, a profile or an account.','Leaders do not give legal or financial advice. They point to a qualified professional.',array['rising','builders','stewards']::text[],'weeknight-evening','online','Earns from creative work and speaks honestly about the money side. Practical and generous.',3,1,3,2,false)
    ) as v (slug, community_slug, family_slug, title, sort,
            who_for, loving_god, loving_others, loving_life, week12_outcome, arc_1, arc_2, arc_3, guardrail, track_slugs,
            rhythm_slot, rhythm_mode, who_leads_well, ds, dc, dt, dd, sensitive)
    join public.communities c on c.slug = v.community_slug
    join public.goal_families f on f.slug = v.family_slug
  on conflict (slug) do nothing;

  select count(*) into v_n from public.tribe_card_templates;
  if v_n <> 23 then
    raise exception 'Expected 23 card templates after the seed, found %', v_n;
  end if;

  -- These 23 are the goals that already exist. They keep their identity: link each by slug, community and title, and stop if
  -- any is missing or different. Signing one of these cards off creates no goal and leaves the goal's three ideas as they were.
  update public.tribe_card_templates t
     set season_goal_id = g.id
    from public.season_goals g
   where g.slug = t.slug and g.community_id = t.community_id and lower(g.title) = lower(t.title) and t.season_goal_id is null;
  select count(*) into v_n from public.tribe_card_templates where season_goal_id is not null;
  if v_n <> 23 then
    raise exception 'Expected 23 card templates linked to live goals, found %', v_n;
  end if;

  -- Their weekly ideas on the card must equal the ideas the migrated database holds today, word for word.
  select count(*) into v_n
    from public.tribe_card_templates t
   where t.season_goal_id is not null
     and ((select i.idea from public.goal_ideas i where i.season_goal_id = t.season_goal_id and i.phase = 1) is distinct from t.arc_1
       or (select i.idea from public.goal_ideas i where i.season_goal_id = t.season_goal_id and i.phase = 2) is distinct from t.arc_2
       or (select i.idea from public.goal_ideas i where i.season_goal_id = t.season_goal_id and i.phase = 3) is distinct from t.arc_3);
  if v_n <> 0 then
    raise exception '% of the 23 live cards have weekly ideas that differ from the live ones', v_n;
  end if;
end
$seed$;
